// Extraire le texte OCR du document Paperless
const doc = $input.first().json;
const ocrText = doc.content || doc.original_file_name || '';
const documentId = doc.id;
const fileName = doc.original_file_name || doc.title;

if (!ocrText || ocrText.trim().length < 20) {
  return [{
    json: {
      document_id: documentId,
      file_name: fileName,
      ocr_text: ocrText,
      error: 'Texte OCR trop court ou vide',
      skip: true
    }
  }];
}

return [{
  json: {
    document_id: documentId,
    file_name: fileName,
    ocr_text: ocrText.substring(0, 8000), // Limiter pour le LLM
    skip: false
  }
}];

// Préparer le prompt pour Ollama Mistral
const data = $input.first().json;
const ocrText = data.ocr_text;

const systemPrompt = `Tu es un assistant expert en analyse de documents administratifs et financiers français.
Analyse le texte OCR du document et extrais les informations structurées.

RÈGLES STRICTES :
1. Réponds UNIQUEMENT avec un objet JSON valide, sans markdown, sans explication.
2. Si une information est absente ou incertaine, utilise null (sans guillemets).
3. Les montants sont en euros, format décimal avec point (ex: 125.50).
4. Les dates sont au format ISO 8601 : YYYY-MM-DD.
5. Pour l'IBAN, extraire le format complet ou null.
6. Ne jamais inventer d'informations non présentes dans le texte.

TYPES DE DOCUMENTS :
- "facture" : une facture à payer
- "rappel" : un rappel de paiement, mise en demeure, relance
- "courrier_administratif" : courrier officiel d'une administration
- "attestation" : certificat, attestation, quittance, reçu

FORMAT JSON ATTENDU :
{
  "emetteur": "Nom émetteur",
  "type_document": "facture|rappel|courrier_administratif|attestation",
  "montant_total": 0.00,
  "date_document": "YYYY-MM-DD",
  "date_echeance": "YYYY-MM-DD",
  "iban": null,
  "bic": null,
  "communication": null,
  "numero_facture": null,
  "statut_paiement": "Non Payé|Payé|Rappel Reçu|En Litige",
  "notes": null
}

TEXTE DU DOCUMENT :\n${ocrText}`;

// Retourner avec le prompt préparé
return [{
  json: {
    ...data,
    prompt_text: systemPrompt
  }
}];

// Parser la réponse JSON de Mistral
const ollamaResponse = $input.first().json;
const rawResponse = ollamaResponse.response || '';
const documentData = $('Extraire Texte OCR').first().json;

let parsed = {};
try {
  // Nettoyer la réponse (retirer markdown si présent)
  let cleaned = rawResponse
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();

  // Trouver le premier objet JSON valide
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Pas de JSON trouvé dans la réponse');
  }
} catch (e) {
  // Valeurs par défaut si parsing échoué
  parsed = {
    emetteur: null,
    type_document: 'courrier_administratif',
    montant_total: null,
    date_document: null,
    date_echeance: null,
    iban: null,
    bic: null,
    communication: null,
    numero_facture: null,
    statut_paiement: 'Non Payé',
    notes: `Erreur parsing IA: ${e.message}`
  };
}

// Normalisation des valeurs
const normalize = (obj) => {
  if (obj.montant_total !== null && typeof obj.montant_total === 'string') {
    obj.montant_total = parseFloat(obj.montant_total.replace(',', '.').replace(/[^0-9.]/g, '')) || null;
  }
  if (!['facture', 'rappel', 'courrier_administratif', 'attestation'].includes(obj.type_document)) {
    obj.type_document = 'courrier_administratif';
  }
  if (!['Non Payé', 'Payé', 'En Litige', 'Rappel Reçu'].includes(obj.statut_paiement)) {
    obj.statut_paiement = obj.type_document === 'rappel' ? 'Rappel Reçu' : 'Non Payé';
  }
  return obj;
};

parsed = normalize(parsed);

// Générer QR Code EPC si IBAN disponible
let qrCodeUrl = null;
if (parsed.iban && parsed.montant_total) {
  const ibanClean = parsed.iban.replace(/\s/g, '');
  const amount = parsed.montant_total.toFixed(2);
  const beneficiary = (parsed.emetteur || 'Bénéficiaire').substring(0, 70);
  const ref = (parsed.communication || parsed.numero_facture || '').substring(0, 140);
  // Format EPC QR Code (SEPA)
  const epcData = `BCD\n002\n1\nSCT\n${parsed.bic || ''}\n${beneficiary}\n${ibanClean}\nEUR${amount}\n\n${ref}`;
  qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(epcData)}`;
  // Note: En production, générer le QR localement pour rester 100% privé
}

return [{
  json: {
    document_id: documentData.document_id,
    file_name: documentData.file_name,
    ...parsed,
    qr_code_url: qrCodeUrl,
    processed_at: new Date().toISOString()
  }
}];

